package ui;

import static utils.ui.UiDrawing.*;
import dev.tamboui.buffer.Cell;
import dev.tamboui.layout.Rect;
import dev.tamboui.terminal.Frame;
import dev.tamboui.widgets.gauge.Gauge;
import dev.tamboui.widgets.paragraph.Paragraph;
import dev.tamboui.style.Overflow;
import generation.progress.GenerationSnapshot;

// Generated by ChatGPT-6-Astra for TUI design
// Menu and generation screens reuse the grading UI's colours, borders, and resource panel.
final class SessionScreen {
    private SessionScreen() {}

    // TUI design for the menu
    static void menu(Frame frame, UiSession session, int selected, ResourceUsage.Sample resources) {
        Rect body = shell(frame, "menu", "[↑/↓] select  [enter] run  [q] quit", resources);
        if (body == null) return;
        drawLine(frame, body, 0, "project > " + session.config().getInputDirectory(), muted);
        drawLine(frame, body, 1, "testers > " + session.activeTesters(), cyan);
        String[] options = {"[1] generate testers", "[2] run grading", "[3] quit"};
        for (int i = 0; i < options.length; i++)
            drawLine(frame, body, i + 3, (selected == i ? "> " : "  ") + options[i], selected == i ? cyan : base);
        if (body.height() > 7) frame.renderWidget(Paragraph.builder().text(safeText(session.notice()))
                .style(muted).overflow(Overflow.WRAP_WORD).build(),
                new Rect(body.x(), body.y() + 7, body.width(), body.height() - 7));
    }

    // TUI design for the generation & generation loading
    static void generation(Frame frame, GenerationSnapshot snapshot, String commands, ResourceUsage.Sample resources) {
        Rect body = shell(frame, snapshot.finished() ? "generation summary" : "tester generation", commands, resources);
        if (body == null) return;
        drawLine(frame, body, 0, snapshot.finished() ? (snapshot.failed() ? "generation stopped / incomplete" : "generation complete")
                : "|/-\\".charAt((int) (snapshot.elapsed().toMillis() / 250 % 4)) + " " + snapshot.message(),
                snapshot.failed() ? red : cyan);
        drawLine(frame, body, 1, "elapsed > " + snapshot.elapsed().toSeconds() + "s", muted);
        
        // This bar measures validated outcomes, not the unknown duration of the AI request.
        if (body.height() > 2 && !snapshot.questions().isEmpty())
            frame.renderWidget(Gauge.builder().ratio(snapshot.ratio()).label(snapshot.outcomes().size() + "/" + snapshot.questions().size() + " processed")
                    .style(base).gaugeStyle(cyan).build(), new Rect(body.x(), body.y() + 2, body.width(), 1));
        if (snapshot.finished() && snapshot.outcomes().isEmpty() && body.height() > 3) {
            frame.renderWidget(Paragraph.builder().text(safeText(snapshot.message())).style(snapshot.failed() ? red : base)
                    .overflow(Overflow.WRAP_WORD).build(), new Rect(body.x(), body.y() + 3, body.width(), body.height() - 3));
            return;
        }
        int rows = Math.max(0, body.height() - 5);
        int start = Math.max(0, snapshot.outcomes().size() - rows);
        for (int i = start; i < snapshot.outcomes().size(); i++) {
            var outcome = snapshot.outcomes().get(i);
            drawLine(frame, body, 4 + i - start, outcome.questionId() + " > " + outcome.status() + " > " + outcome.message(), base);
        }
        drawLine(frame, body, body.height() - 1, snapshot.finished() ? snapshot.message()
                : snapshot.currentQuestion().isEmpty() ? "waiting for tester results" : "checking > " + snapshot.currentQuestion(), muted);
    }

    // TUI design for the main boxes
    private static Rect shell(Frame frame, String title, String commands, ResourceUsage.Sample resources) {
        frame.buffer().fill(frame.area(), new Cell(" ", base));
        if (frame.width() < 32 || frame.height() < 16) {
            frame.renderWidget(Paragraph.builder().text("terminal too small\nresize to at least 32 x 16").style(base).build(), frame.area());
            return null;
        }
        int width = Math.min(frame.width() - 2, 96), height = Math.min(frame.height(), 30);
        Rect inside = box(frame, new Rect((frame.width() - width) / 2, 0, width, height), "evil autograder");
        Rect footer = box(frame, new Rect(inside.x(), inside.y() + inside.height() - 3, inside.width(), 3), "commands");
        drawLine(frame, footer, 0, commands, cyan);
        // Small terminals reserve the available space for the operation itself.
        int resourceHeight = height >= 23 ? 5 : 0;
        if (resourceHeight > 0) {
            Rect metrics = box(frame, new Rect(inside.x(), footer.y() - 1 - resourceHeight, inside.width(), resourceHeight), "resource usage");
            drawLine(frame, metrics, 0, resources.summary(), muted);
            drawLine(frame, metrics, 1, "threads > " + resources.threads(), muted);
        }
        return box(frame, new Rect(inside.x(), inside.y(), inside.width(), inside.height() - 3 - resourceHeight), title);
    }
}
